import pathlib,subprocess,time,json,os
R=pathlib.Path(__file__).parent
with (R/'serial.log').open('w') as log:
 p=subprocess.Popen(['bash',str(R/'launch.sh')],stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT)
 (R/'supervisor-pid').write_text(str(p.pid))
 evidence=[]
 for i in range(300):
  time.sleep(1)
  for d in pathlib.Path('/proc').glob('[0-9]*'):
   try:
    argv=(d/'cmdline').read_bytes().replace(b'\0',b' ').decode()
    if '/home/cody/.hermes/cache/scratch/xr-guest-build/qemu/usr/bin/qemu-system-x86_64' in argv and '-machine q35' in argv and 'timeout' not in argv and 'python' not in argv:
     evidence.append({'pid':d.name,'argv':argv,'fds':{x.name:os.readlink(x) for x in (d/'fd').iterdir()}})
   except (OSError,UnicodeError): pass
  if p.poll() is not None: break
 (R/'host-isolation.json').write_text(json.dumps(evidence,indent=2))
 code=p.wait(timeout=440)
 survivors=[]
 for d in pathlib.Path('/proc').glob('[0-9]*'):
  try:
   argv=(d/'cmdline').read_bytes().replace(b'\0',b' ').decode()
   if argv.startswith('/home/cody/.hermes/cache/scratch/xr-guest-build/qemu/usr/bin/qemu-system-x86_64'):survivors.append(d.name)
  except (OSError,UnicodeError):pass
 result={'exit_code':code,'supervisor_pid':p.pid,'qemu_survivors':survivors}
 (R/'exit.json').write_text(json.dumps(result,indent=2)); print(result)

