"""Host image-only preparation; immutable source copies, no host service/config changes."""
import pathlib,subprocess,json,hashlib,re
P=pathlib.Path;r=P(__file__).parent;repo=P('/home/cody/Projects/viture-workspace/.worktrees/settings-panel')
files={}
def tree(src,dst):
 for p in P(src).rglob('*'):
  if p.is_file(): files[str(P(dst)/p.relative_to(src))]=p
for src,dst in [('/usr/lib/qt6/qml','/usr/lib/qt6/qml'),('/usr/lib/qt6/plugins','/usr/lib/qt6/plugins'),
 ('/usr/share/omarchy/shell/Commons','/opt/xr/panel/Commons'),('/usr/share/omarchy/shell/Ui','/opt/xr/panel/Ui'),
 (repo/'omarchy-plugin/cody.viture-workspace','/opt/xr/panel/plugin')]:tree(src,dst)
files['/usr/bin/quickshell']=P('/usr/bin/quickshell')
for path in list(files.values()):
 if path.read_bytes()[:4]!=b'\x7fELF':continue
 s=subprocess.run(['ldd',str(path)],capture_output=True,text=True).stdout
 for lib in re.findall(r'(?:=> )?(/[^\s]+)',s):
  if P(lib).is_file():files[str(P(lib).parent.resolve()/P(lib).name)]=P(lib)
qml=r/'shell.qml';qml.write_text('''import QtQuick
import Quickshell
import "plugin" as Plugin
ShellRoot {
 Plugin.Panel { id: panel; Component.onCompleted: open({}) }
 Timer { interval: 1000; running: true; repeat: true; onTriggered: console.log("VM_PANEL_STATE", panel.snapshot.state) }
}
''');files['/opt/xr/panel/shell.qml']=qml
# Copy font used by existing HUD if present; no font downloads.
for p in P('/usr/share/fonts').rglob('*.ttf'):
 if 'JetBrainsMonoNerdFont-Regular' in p.name:files[str(p)]=p
files={dst:src.resolve() for dst,src in files.items()}
commands=[];dirs=set()
for dst in files:
 for d in P(dst).parents:
  if str(d)!='/':dirs.add(str(d))
for d in sorted(dirs,key=lambda x:(x.count('/'),x)):commands.append('mkdir '+d)
for dst,src in files.items():
 commands += ['rm '+dst,f'write {src} {dst}',f'set_inode_field {dst} uid 0',f'set_inode_field {dst} gid 0',f'set_inode_field {dst} mode '+('0100755' if src.stat().st_mode & 0o111 else '0100644')]
(r/'extras.commands').write_text('\n'.join(commands)+'\n')
with (r/'extras.log').open('w') as log:subprocess.run(['debugfs','-w','-f',str(r/'extras.commands'),str(r/'guest.raw')],stdout=log,stderr=log,check=True)
manifest={}
for dst,src in files.items():
 got=subprocess.run(['debugfs','-R','cat '+dst,str(r/'guest.raw')],capture_output=True,check=True).stdout
 assert got==src.read_bytes(),dst
 manifest[dst]=hashlib.sha256(got).hexdigest()
(r/'extras-manifest.json').write_text(json.dumps(manifest,indent=2));print('Extra image files verified',len(manifest))
